      const downCount = state.feedback.filter((f) => f.signal === "thumbs-down").length;
      const confusedCount = state.feedback.filter((f) => f.signal === "confused").length;
      const feedbackTopics = feedbackOnlyTopics(state);
      const lines = [
        `Sessions: ${state.sessions?.length ?? 0}`,
        `Topics covered: ${state.coveredTopics.length}`,
        ...state.coveredTopics.slice(-10).map((t) => ` - ${t.slug} (${t.domain})`),
        ...(feedbackTopics.length > 0
          ? [`Feedback-only topics: ${feedbackTopics.length}`, ...feedbackTopics.map((topic) => ` - ${topic}`)]
          : []),
        `Feedback: 👍${upCount} 👎${downCount} 🤔${confusedCount}`,
        `Misconceptions identified: ${state.identifiedMisconceptions.length}`,
      ];
      ctx.ui.setEditorText(lines.join("\n"));
      info(ctx, "Learner profile loaded.");
    }
  });

  pi.registerCommand("timeline", {
    description: "Show the engagement timeline for all covered topics, sorted by review urgency.",
    handler: async (_args: string[], ctx: any) => {
      const artifact = await timelineArtifact(ctx.cwd);
      ctx.ui.setEditorText(artifact.markdown);
      info(ctx, `Engagement timeline saved to ${relative(ctx.cwd, artifact.reportPath)}`);
    }
  });

  pi.registerCommand("due", {
    description: "Show topics that are due for review based on spaced repetition.",
    handler: async (_args: string[], ctx: any) => {
      const artifact = await dueTopicsArtifact(ctx.cwd);
      ctx.ui.setEditorText(artifact.markdown);
      if (artifact.count === 0) {
        info(ctx, "All topics are up to date! No reviews needed.");
      } else {
        info(ctx, `${artifact.count} topic${artifact.count === 1 ? "" : "s"} due for review.`);
      }
    }
  });

  pi.on("session_start", async (_event: any, ctx: any) => {
    await ensureProjectScaffold(ctx.cwd);
    // Record session start in learner state
    const statePath = learnerStatePath(ctx.cwd);
    const state = await loadLearnerState(statePath);
    recordSessionStart(state);
    await saveLearnerState(statePath, state);
    const config = await loadKeatingConfig(ctx.cwd);
    setActiveCtx(ctx);
    registerKeatingTools(pi);
    registerSpeechTool(pi, config);
    const configuredProvider = config.pi.defaultProvider ?? DEFAULT_PI_PROVIDER;
    const missingProvider = process.env.KEATING_AUTH_MISSING_PROVIDER || "";
    const hasConfiguredProvider = providerIsConfigured(ctx.cwd, envWithProviderAliases(process.env), configuredProvider);
    if (missingProvider || (!hasConfiguredProvider && config.debug.consoleSummary)) {
      info(ctx, providerSetupMessage(missingProvider || configuredProvider));
    }

    // ─── Branded greeting on first session in this process ───────────────
    if (!greetingShown) {
      greetingShown = true;
      if (ctx.hasUI !== false && typeof ctx.ui.setHeader === "function") {
        ctx.ui.setHeader(createKeatingHeaderComponent(pi, ctx));
      } else if (typeof ctx.ui.setWidget === "function") {
        ctx.ui.setWidget("keating-greeting", createKeatingHeaderComponent(pi, ctx));
      }
    }

    // Check for due topics and notify
    const dueArtifact = await dueTopicsArtifact(ctx.cwd);
    if (config.debug.consoleSummary) {
      if (dueArtifact.count > 0) {
        info(ctx, `Keating loaded. ${dueArtifact.count} topic${dueArtifact.count === 1 ? " is" : "s are"} due for review. Use /due to see them.`);
      } else {
        info(ctx, `Keating loaded — ready to teach. Type a topic or a command.`);
      }
    }
  });
}
import { readFileSync } from "node:fs";
import {
  Input,
  SelectList,
  type Component,
  type SelectItem,
  truncateToWidth,
  wrapTextWithAnsi,
} from "@earendil-works/pi-tui";
import { getSelectListTheme } from "@earendil-works/pi-coding-agent";
import type { Quiz, QuizQuestion } from "../../core/quiz.js";
import type { LearnerGoal } from "../../core/goals.js";

// pi's Theme type isn't re-exported at a stable path we can safely import from an
// extension package; every other Component builder in hyperteacher-extension.ts
// treats it as `any` too (see createKeatingHeaderComponent), so we match that.
type Theme = any;

function pad(text: string, width: number): string {
  return truncateToWidth(text, Math.max(0, width), "…", true);
}

function wrap(text: string, width: number): string[] {
  return wrapTextWithAnsi(text, Math.max(1, width));
}

/** A static (non-interactive) bordered card, matching the visual style of createKeatingHeaderComponent. */
export function renderCard(theme: Theme, heading: string, bodyLines: string[]): Component {
  const t = theme.fg.bind(theme);
  const b = theme.bold.bind(theme);
  const border = (text: string) => t("borderMuted", text);
  const headingText = b(t("mdHeading", heading));

  return {
    render(width: number): string[] {
      const cardWidth = Math.min(Math.max(width - 2, 20), 100);
      const innerWidth = cardWidth - 4;
      const lines: string[] = [];
      lines.push(border(`╭${"─".repeat(cardWidth - 2)}╮`));
      lines.push(`${border("│")} ${pad(headingText, innerWidth)} ${border("│")}`);
      lines.push(`${border("├")}${border("─".repeat(cardWidth - 2))}${border("┤")}`);
      for (const raw of bodyLines) {
        const wrapped = raw.length === 0 ? [""] : wrap(raw, innerWidth);
        for (const line of wrapped) {
          lines.push(`${border("│")} ${pad(line, innerWidth)} ${border("│")}`);
        }
      }
      lines.push(border(`╰${"─".repeat(cardWidth - 2)}╯`));
      return lines;
    },
    invalidate() {},
  };
}

/** Reads a just-written artifact file from disk and renders it as a bordered markdown preview. */
export function renderArtifactPreview(theme: Theme, title: string, filePath: string, maxLines = 40): Component {
  let bodyLines: string[];
  try {
    const raw = readFileSync(filePath, "utf8");
    const allLines = raw.split("\n");
    bodyLines = allLines.slice(0, maxLines);
    if (allLines.length > maxLines) {
      bodyLines.push("", `… ${allLines.length - maxLines} more lines (see ${filePath})`);
    }
  } catch {
    bodyLines = [`(could not read ${filePath})`];
  }
  return renderCard(theme, title, bodyLines);
}

const QUESTION_STATUS_GLYPH: Record<"unanswered" | "answered" | "correct" | "incorrect" | "pending_grade", string> = {
  unanswered: "○",
  answered: "●",
  correct: "✓",
  incorrect: "✗",
  pending_grade: "…",
};

export interface QuizCardState {
  answers?: Map<string, string>;
  objectiveResults?: Map<string, boolean>;
  openEndedGrades?: Map<string, { verdict: "correct" | "incorrect" | "partial"; note?: string }>;
}

function questionStatus(q: QuizQuestion, state: QuizCardState): keyof typeof QUESTION_STATUS_GLYPH {
  const graded = state.openEndedGrades?.get(q.id);
  if (graded) return graded.verdict === "partial" ? "answered" : graded.verdict;
  const objective = state.objectiveResults?.get(q.id);
  if (objective !== undefined) return objective ? "correct" : "incorrect";
  const isOpenEnded = q.type === "short_answer" || q.type === "transfer";
  if (isOpenEnded && state.answers?.has(q.id)) return "pending_grade";
  return state.answers?.has(q.id) ? "answered" : "unanswered";
}

export function renderQuizCard(theme: Theme, quiz: Quiz, state: QuizCardState = {}): Component {
  const lines: string[] = [];
  let correct = 0;
  let graded = 0;
  for (const q of quiz.questions) {
    const status = questionStatus(q, state);
    if (status === "correct") correct++;
    if (status === "correct" || status === "incorrect") graded++;
    lines.push(`${QUESTION_STATUS_GLYPH[status]} [${q.level}] ${q.question}`);
    const answer = state.answers?.get(q.id);
    if (answer) lines.push(`   your answer: ${answer}`);
    const note = state.openEndedGrades?.get(q.id)?.note;
    if (note) lines.push(`   feedback: ${note}`);
  }
  if (graded > 0) {
    lines.unshift("", `Objective score: ${correct}/${graded}`);
  }
  return renderCard(theme, `Quiz: ${quiz.topic}`, lines);
}

function progressBar(percent: number, width = 20): string {
  const filled = Math.round((Math.max(0, Math.min(100, percent)) / 100) * width);
  return `[${"#".repeat(filled)}${"-".repeat(width - filled)}] ${percent}%`;
}

const GOAL_STEP_GLYPH: Record<string, string> = {
  not_started: "[ ]",
  in_progress: "[~]",
  done: "[x]",
};

export function renderGoalCard(theme: Theme, goal: LearnerGoal): Component {
  const total = goal.steps.length;
  const done = goal.steps.filter((s) => s.status === "done").length;
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  const nextStep = goal.steps.find((s) => s.status !== "done");

  const lines: string[] = [];
  if (goal.description) lines.push(goal.description, "");
  lines.push(`Progress: ${progressBar(percent)} (${done}/${total})`, `Status: ${goal.status}`);
  if (nextStep) lines.push(`Next: ${nextStep.title}`);
  lines.push("");
  for (const step of goal.steps) {
    lines.push(`${GOAL_STEP_GLYPH[step.status] ?? "[ ]"} ${step.order + 1}. ${step.title} (${step.kind})`);
  }
  return renderCard(theme, `Goal: ${goal.title}`, lines);
}

export function renderGoalListCard(theme: Theme, goals: LearnerGoal[]): Component {
  if (goals.length === 0) return renderCard(theme, "Learner Goals", ["No goals yet."]);
  const lines = goals.map((g) => {
    const total = g.steps.length;
    const done = g.steps.filter((s) => s.status === "done").length;
    return `${g.status === "completed" ? "✓" : "•"} [${g.id}] ${g.title} — ${done}/${total} steps (${g.status})`;
  });
  return renderCard(theme, "Learner Goals", lines);
}

// ─── Interactive answer collection ─────────────────────────────────────────

export type AnswerFormKind = "choice" | "text" | "blanks" | "classification" | "matching";

export interface AnswerFormQuestion {
  id: string;
  prompt: string;
  kind: AnswerFormKind;
  choices?: string[];
  items?: string[];
  allowText?: boolean;
  requireReasons?: boolean;
  uniqueMatches?: boolean;
}

export interface AnswerFormResult {
  [questionId: string]: string;
}

const OTHER_ITEM_VALUE = "__answer_form_other__";

/**
 * A blocking, keyboard-driven form. Renders one or more questions vertically;
 * only the focused row receives keystrokes. Supports choice (SelectList),
 * free text (Input), and per-row choice sequences for classification/matching
 * (one SelectList + optional reason Input per item/row).
 */
interface FormRow {
  questionId: string;
  label: string;
  control: SelectList | Input;
  /** A follow-up Input shown after `control` is confirmed (e.g. a classification reason, or free text for "Other"). */
  followUpControl?: Input;
  /** "always": ask the follow-up regardless of the primary selection. "on-other": only when OTHER_ITEM_VALUE was picked. */
  followUpTrigger?: "always" | "on-other";
}

export class AnswerFormComponent implements Component {
  private theme: Theme;
  private questions: AnswerFormQuestion[];
  private rows: FormRow[] = [];
  private focusIndex = 0;
  /** true once the focused row's primary control is confirmed and its reasonControl (if any) is active. */
  private onReasonStep = false;
  private answers = new Map<string, string>();
  private done: (result: AnswerFormResult) => void;
  invalidate: () => void = () => {};

  constructor(theme: Theme, questions: AnswerFormQuestion[], done: (result: AnswerFormResult) => void) {
    this.theme = theme;
    this.questions = questions;
    this.done = done;
    this.buildRows();
  }

  private buildRows(): void {
    const selectTheme = getSelectListTheme();
    for (const q of this.questions) {
      if (q.kind === "choice" && q.choices && q.choices.length > 0) {
        const items: SelectItem[] = q.choices.map((c) => ({ value: c, label: c }));
        if (q.allowText) items.push({ value: OTHER_ITEM_VALUE, label: "Other (type your own answer)" });
        this.rows.push({
          questionId: q.id,
          label: q.prompt,
          control: new SelectList(items, 8, selectTheme),
          followUpControl: q.allowText ? new Input() : undefined,
          followUpTrigger: "on-other",
        });
      } else if (q.kind === "classification" || q.kind === "matching") {
        const rowItems = q.items ?? [];
        for (const [idx, item] of rowItems.entries()) {
          const choiceItems: SelectItem[] = (q.choices ?? []).map((c) => ({ value: c, label: c }));
          this.rows.push({
            questionId: `${q.id}::${idx}`,
            label: `${item} →`,
            control: new SelectList(choiceItems, 8, selectTheme),
            followUpControl: q.kind === "classification" && q.requireReasons ? new Input() : undefined,
            followUpTrigger: "always",
          });
        }
      } else {
        this.rows.push({ questionId: q.id, label: q.prompt, control: new Input() });
      }
    }
  }

  private currentControl(): SelectList | Input | undefined {
    const row = this.rows[this.focusIndex];
    if (!row) return undefined;
    return this.onReasonStep && row.followUpControl ? row.followUpControl : row.control;
  }

  private advance(): void {
    this.onReasonStep = false;
    if (this.focusIndex < this.rows.length - 1) {
      this.focusIndex += 1;
      this.invalidate();
    } else {
      this.done(Object.fromEntries(this.answers));
    }
  }

  private confirmCurrentControl(): void {
    const row = this.rows[this.focusIndex];
    if (!row) return;
    if (!this.onReasonStep) {
      const value = row.control instanceof SelectList
        ? (row.control.getSelectedItem()?.value ?? "")
        : (row.control as Input).getValue();
      this.answers.set(row.questionId, value);
      const needsFollowUp =
        row.followUpControl &&
        (row.followUpTrigger === "always" || (row.followUpTrigger === "on-other" && value === OTHER_ITEM_VALUE));
      if (needsFollowUp) {
        this.onReasonStep = true;
        this.invalidate();
        return;
      }
      this.advance();
      return;
    }
    if (row.followUpControl) {
      const key = row.followUpTrigger === "on-other" ? row.questionId : `${row.questionId}::reason`;
      this.answers.set(key, row.followUpControl.getValue());
    }
    this.advance();
  }

  handleInput(data: string): void {
    if (data === "\r" || data === "\n") {
      this.confirmCurrentControl();
      return;
    }
    if (data === "\x1b") {
      this.done(Object.fromEntries(this.answers));
      return;
    }
    this.currentControl()?.handleInput(data);
    this.invalidate();
  }

  render(width: number): string[] {
    const t = this.theme.fg.bind(this.theme);
    const b = this.theme.bold.bind(this.theme);
    const lines: string[] = [];
    for (const q of this.questions) {
      lines.push(b(t("mdHeading", q.prompt)));
    }
    lines.push("");
    this.rows.forEach((row, idx) => {
      const isFocused = idx === this.focusIndex;
      const marker = isFocused ? t("accent", "▸ ") : "  ";
      lines.push(`${marker}${row.label}`);
      if (isFocused || this.answers.has(row.questionId)) {
        const controlLines = row.control.render(Math.max(10, width - 4));
        for (const line of controlLines) lines.push(`    ${line}`);
      }
      if (row.followUpControl && isFocused && this.onReasonStep) {
        lines.push(`    ${t("dim", row.followUpTrigger === "always" ? "reason:" : "your answer:")}`);
        for (const line of row.followUpControl.render(Math.max(10, width - 4))) lines.push(`    ${line}`);
      }
    });
    lines.push("", t("dim", "type or use arrow keys + Enter to confirm each row · Esc to submit early"));
    return lines;
  }
}

import {
  BoxRenderable,
  InputRenderable,
  SelectRenderable,
  SelectRenderableEvents,
  ScrollBoxRenderable,
  TextRenderable,
  createCliRenderer,
} from "@opentui/core";

import { launchRpcClient } from "../runtime/pi.js";
import { HostController, type HostSurface } from "./host-controller.js";

export type OpenTuiExitAction = "exit" | "shell";

/** Run the alternate OpenTUI host over Pi RPC. `keating shell` remains intact. */
export async function launchOpenTui(cwd: string, initialPrompt?: string): Promise<OpenTuiExitAction> {
  const client = await launchRpcClient(cwd);
  let settle: ((action: OpenTuiExitAction) => void) | null = null;
  let settled = false;
  const result = new Promise<OpenTuiExitAction>((resolve) => { settle = resolve; });
  const renderer = await createCliRenderer({
    exitOnCtrlC: true,
    clearOnShutdown: true,
    backgroundColor: "#11100e",
    onDestroy: () => {
      if (!settled) {
        settled = true;
        settle?.("exit");
      }
      void client.stop();
    },
  });

  const shell = new BoxRenderable(renderer, {
    id: "keating-open-tui",
    width: "100%",
    height: "100%",
    flexDirection: "column",
    padding: 1,
    gap: 1,
    backgroundColor: "#11100e",
  });
  const header = new TextRenderable(renderer, {
    id: "keating-open-tui-header",
    content: "KEATING  ·  collaborative teaching host",
    fg: "#d6a84d",
    height: 1,
  });
  const status = new TextRenderable(renderer, {
    id: "keating-open-tui-status",
    content: "Pi RPC connected  ·  /shell switches to the classic Pi interface",
    fg: "#9d9485",
    height: 1,
  });
  const scroll = new ScrollBoxRenderable(renderer, {
    id: "keating-open-tui-transcript-scroll",
    flexGrow: 1,
    width: "100%",
    border: true,
    borderStyle: "single",
    borderColor: "#4c463d",
    padding: 1,
    scrollY: true,
    stickyScroll: true,
    stickyStart: "bottom",
  });
  const transcript = new TextRenderable(renderer, {
    id: "keating-open-tui-transcript",
    content: "Ask a question, continue a learning goal, or type /shell for the classic Pi interface.",
    fg: "#eee8dc",
    width: "100%",
  });
  const inputFrame = new BoxRenderable(renderer, {
    id: "keating-open-tui-input-frame",
    width: "100%",
    height: 3,
    border: true,
    borderStyle: "single",
    borderColor: "#d6a84d",
    paddingLeft: 1,
    paddingRight: 1,
  });
  const input = new InputRenderable(renderer, {
    id: "keating-open-tui-input",
    width: "100%",
    placeholder: "Message Keating…",
    textColor: "#eee8dc",
    placeholderColor: "#81786b",
    backgroundColor: "#11100e",
    focusedBackgroundColor: "#11100e",
    focusedTextColor: "#ffffff",
  });

  scroll.add(transcript);
  inputFrame.add(input);
  shell.add(header);
  shell.add(status);
  shell.add(scroll);
  shell.add(inputFrame);
  renderer.root.add(shell);

  const turns: string[] = [];
  let streaming = "";
  let busy = false;
  let dialogCancel: (() => void) | null = null;
  const renderTranscript = () => {
    transcript.content = [...turns, streaming].filter(Boolean).join("\n\n");
    scroll.scrollTo({ y: scroll.scrollHeight, x: 0 });
  };
  const appendTurn = (message: string) => {
    turns.push(message);
    renderTranscript();
  };

  const presentSelect = (title: string, options: string[]): Promise<string | undefined> =>
    new Promise((resolve) => {
      const modal = new BoxRenderable(renderer, {
        id: `keating-dialog-${Date.now()}`,
        width: "100%",
        height: Math.min(Math.max(options.length + 4, 6), 16),
        flexDirection: "column",
        border: true,
        borderStyle: "single",
        borderColor: "#d6a84d",
        padding: 1,
      });
      const titleView = new TextRenderable(renderer, { content: `${title}  ·  Esc cancels`, fg: "#d6a84d", height: 1 });
      const select = new SelectRenderable(renderer, {
        id: `keating-select-${Date.now()}`,
        flexGrow: 1,
        options: options.map((option) => ({ name: option, description: "", value: option })),
        showDescription: false,
        wrapSelection: true,
        selectedBackgroundColor: "#d6a84d",
        selectedTextColor: "#11100e",
      });
      modal.add(titleView);
      modal.add(select);
      shell.add(modal, 3);
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        shell.remove(modal);
        renderer.focusRenderable(input);
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      select.on(SelectRenderableEvents.ITEM_SELECTED, () => finish(select.getSelectedOption()?.value as string | undefined));
      renderer.focusRenderable(select);
    });

  const presentTextInput = (title: string, prefill?: string, placeholder?: string): Promise<string | undefined> =>
    new Promise((resolve) => {
      status.content = `${title}  ·  Enter submits  ·  Esc cancels`;
      input.value = prefill ?? "";
      input.placeholder = placeholder ?? "Type a response…";
      const previousSubmit = input.onSubmit;
      let done = false;
      const finish = (value?: string) => {
        if (done) return;
        done = true;
        dialogCancel = null;
        input.onSubmit = previousSubmit;
        input.placeholder = "Message Keating…";
        input.value = "";
        status.content = "Ready  ·  /shell switches to classic Pi  ·  Ctrl+C exits";
        resolve(value);
      };
      dialogCancel = () => finish(undefined);
      input.onSubmit = () => finish(input.value);
      renderer.focusRenderable(input);
    });

  const surface: HostSurface = {
    appendTurn,
    setStreaming(text) { streaming = text ?? ""; renderTranscript(); },
    setStatus(text) { status.content = text; },
    setBusy(value) {
      busy = value;
      status.content = value
        ? "Keating is thinking…  ·  Enter queues a follow-up"
        : "Ready  ·  /shell switches to classic Pi  ·  Ctrl+C exits";
    },
    setEditorText(text) { input.value = text; },
    setWidget(key, lines, placement) {
      if (lines?.length) appendTurn(`[${key}${placement ? ` · ${placement}` : ""}]\n${lines.join("\n")}`);
    },
    setTitle(title) { header.content = title; },
    presentSelect,
    presentConfirm(title, message) { return presentSelect(`${title}\n${message}`, ["Yes", "No"]).then((value) => value === undefined ? undefined : value === "Yes"); },
    presentInput(title, placeholder) { return presentTextInput(title, undefined, placeholder); },
    presentEditor(title, prefill) { return presentTextInput(title, prefill, "Edit response…"); },
  };
  const controller = new HostController(client, surface);
  controller.attach();

  const submit = async (raw: string) => {
    const message = raw.trim();
    if (!message) return;
    input.value = "";
    if (message === "/shell") {
      settled = true;
      settle?.("shell");
      renderer.destroy();
      await client.stop();
      return;
    }
    turns.push(`You\n${message}`);
    renderTranscript();
    try {
      if (busy) await client.followUp(message);
      else await client.prompt(message);
    } catch (error) {
      appendTurn(`[Keating] ${error instanceof Error ? error.message : String(error)}`);
    }
  };

  input.onSubmit = () => { void submit(input.value); };
  renderer.keyInput.on("keypress", (key) => {
    if (key.name === "escape" && dialogCancel) {
      key.preventDefault();
      dialogCancel();
    }
  });
  renderer.focusRenderable(input);
  renderer.start();
  if (initialPrompt?.trim()) void submit(initialPrompt);

  return result;
}
import { toolResultCardLines } from "../core/cards.js";

/**
 * Renderer-free controller for RPC hosts. Translates pi RPC events into
 * calls on a HostSurface, and services extension UI requests (select,
 * confirm, input, editor) by presenting them through the surface and
 * sending extension_ui_response commands back. The OpenTUI host implements
 * HostSurface with real widgets; tests implement it with scripted answers.
 */

export interface HostSurface {
  /** Append a completed transcript entry (user turn, assistant turn, notice, or card). */
  appendTurn(text: string): void;
  /** Replace the in-progress streaming assistant text (null clears it). */
  setStreaming(text: string | null): void;
  setStatus(text: string): void;
  setBusy(busy: boolean): void;
  setEditorText(text: string): void;
  setWidget(key: string, lines: string[] | undefined, placement?: string): void;
  setTitle(title: string): void;
  /** Resolve with the chosen option string, or undefined when cancelled. */
  presentSelect(title: string, options: string[]): Promise<string | undefined>;
  /** Resolve with the decision, or undefined when cancelled. */
  presentConfirm(title: string, message: string): Promise<boolean | undefined>;
  presentInput(title: string, placeholder?: string): Promise<string | undefined>;
  presentEditor(title: string, prefill?: string): Promise<string | undefined>;
}

export interface HostClientLike {
  onEvent(listener: (event: unknown) => void): unknown;
}

interface UiRequestEvent {
  type: "extension_ui_request";
  id?: string;
  method?: string;
  title?: string;
  options?: string[];
  message?: string;
  placeholder?: string;
  prefill?: string;
  statusText?: string;
  text?: string;
  widgetKey?: string;
  widgetLines?: string[];
  widgetPlacement?: string;
  document?: unknown;
}

function messageText(message: unknown): string {
  const content = (message as { content?: unknown } | null)?.content;
  if (typeof content === "string") return content;
  if (!Array.isArray(content)) return "";
  return content
    .map((part) => {
      if (!part || typeof part !== "object") return "";
      const candidate = part as { type?: string; text?: string };
      return candidate.type === "text" && typeof candidate.text === "string" ? candidate.text : "";
    })
    .filter(Boolean)
    .join("\n");
}

function briefArgs(args: unknown): string {
  if (!args || typeof args !== "object") return "";
  const entries = Object.entries(args as Record<string, unknown>)
    .filter(([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean")
    .slice(0, 3)
    .map(([key, value]) => {
      const text = String(value);
      return `${key}=${text.length > 40 ? `${text.slice(0, 40)}…` : text}`;
    });
  return entries.join(", ");
}

export class HostController {
  private client: HostClientLike;
  private surface: HostSurface;
  /** Serializes UI requests: pi awaits each dialog, but never assume only one is outstanding. */
  private uiQueue: Promise<void> = Promise.resolve();

  constructor(client: HostClientLike, surface: HostSurface) {
    this.client = client;
    this.surface = surface;
  }

  attach(): void {
    this.client.onEvent((event) => this.handleEvent(event));
  }

  private async sendUiResponse(requestId: string, response: Record<string, unknown>): Promise<void> {
    const internal = this.client as unknown as { send(command: Record<string, unknown>): Promise<unknown> };
    await internal.send({ type: "extension_ui_response", id: requestId, ...response });
  }

  handleEvent(event: unknown): void {
    const candidate = event as { type?: string } | null;
    if (!candidate || typeof candidate !== "object") return;

    switch (candidate.type) {
      case "message_update": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          const text = messageText(message);
          if (text) this.surface.setStreaming(`Keating\n${text}`);
        }
        return;
      }
      case "message_end": {
        const message = (event as { message?: { role?: string } }).message;
        if (message?.role === "assistant") {
          this.surface.setStreaming(null);
          const text = messageText(message);
          if (text) this.surface.appendTurn(`Keating\n${text}`);
        }
        return;
      }
      case "tool_execution_start": {
        const { toolName, args } = event as { toolName?: string; args?: unknown };
        if (toolName) {
          const summary = briefArgs(args);
          this.surface.appendTurn(`→ ${toolName}${summary ? `(${summary})` : ""}`);
        }
        return;
      }
      case "tool_execution_end": {
        const { toolName, result, isError } = event as { toolName?: string; result?: unknown; isError?: boolean };
        if (!toolName) return;
        if (isError) return;
        const card = toolResultCardLines(toolName, result);
        if (card) this.surface.appendTurn(card.join("\n"));
        return;
      }
      case "agent_start":
        this.surface.setBusy(true);
        return;
      case "agent_end":
        this.surface.setBusy(false);
        return;
      case "extension_ui_request":
        this.handleUiRequest(event as UiRequestEvent);
        return;
      case "ui_document": {
        const { document } = event as { document?: unknown };
        const card = toolResultCardLines("ui_document", document);
        if (card) this.surface.appendTurn(card.join("\n"));
        return;
      }
      default:
        return;
    }
  }

  private handleUiRequest(request: UiRequestEvent): void {
    switch (request.method) {
      case "notify":
        if (request.message) this.surface.appendTurn(`[Keating] ${request.message}`);
        return;
      case "setStatus":
        this.surface.setStatus(request.statusText || "Ready");
        return;
      case "set_editor_text":
        if (typeof request.text === "string") this.surface.setEditorText(request.text);
        return;
      case "setWidget":
        if (request.widgetKey) this.surface.setWidget(request.widgetKey, request.widgetLines, request.widgetPlacement);
        return;
      case "setTitle":
        if (request.title) this.surface.setTitle(request.title);
        return;
      case "select":
      case "confirm":
      case "input":
      case "editor":
        if (request.id) this.enqueueDialog(request as UiRequestEvent & { id: string });
        return;
      default:
        this.surface.appendTurn(`[Keating] Unsupported Pi UI request${request.method ? `: ${request.method}` : ""}. The request was cancelled explicitly.`);
        if (request.id) {
          void this.sendUiResponse(request.id, { cancelled: true, reason: "unsupported_ui_request" }).catch((error) => {
            this.surface.appendTurn(`[Keating] Could not answer UI request: ${error instanceof Error ? error.message : String(error)}`);
          });
        }
        return;
    }
  }

  private enqueueDialog(request: UiRequestEvent & { id: string }): void {
    this.uiQueue = this.uiQueue
      .then(() => this.presentDialog(request))
      .catch((error) => {
        this.surface.appendTurn(`[Keating] UI request failed: ${error instanceof Error ? error.message : String(error)}`);
      });
  }

  private async presentDialog(request: UiRequestEvent & { id: string }): Promise<void> {
    const title = request.title ?? "";
    try {
      switch (request.method) {
        case "select": {
          const value = await this.surface.presentSelect(title, request.options ?? []);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "confirm": {
          const confirmed = await this.surface.presentConfirm(title, request.message ?? "");
          await this.sendUiResponse(request.id, confirmed === undefined ? { cancelled: true } : { confirmed });
          return;
        }
        case "input": {
          const value = await this.surface.presentInput(title, request.placeholder);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        case "editor": {
          const value = await this.surface.presentEditor(title, request.prefill);
          await this.sendUiResponse(request.id, value === undefined ? { cancelled: true } : { value });
          return;
        }
        default:
          await this.sendUiResponse(request.id, { cancelled: true });
      }
    } catch (error) {
      await this.sendUiResponse(request.id, { cancelled: true }).catch(() => {});
      throw error;
    }
  }
}
