 10	export function registerKeatingTools(pi: any): void {
 11	  if (typeof pi.registerTool !== "function") return;
 12	  if (typeof pi === "object" && pi !== null && keatingToolRegistrations.has(pi)) return;
 13	
 14	  const tools = [
 15	    ...teachingTools,
 16	    ...selfEvaluationTools,
 17	    ...selfEvolutionTools,
 18	    ...feedbackTools,
 19	    ...goalTools,
 20	    ...askUserQuestionTools,
 21	  ];
 22	
 23	  for (const tool of tools) {
 24	    pi.registerTool(tool as any);
 25	  }
 26	
 27	  if (typeof pi === "object" && pi !== null) {
 28	    keatingToolRegistrations.add(pi);
 29	  }
