 15	
 16	const DEFAULT_CARD_WIDTH = 76;
 17	
 18	function wrapPlain(text: string, width: number): string[] {
 19	  const lines: string[] = [];
 20	  for (const raw of text.split("\n")) {
 21	    if (raw.length <= width) {
 22	      lines.push(raw);
 23	      continue;
 24	    }
 25	    let rest = raw;
 26	    while (rest.length > width) {
 27	      let cut = rest.lastIndexOf(" ", width);
 28	      if (cut <= 0) cut = width;
 29	      lines.push(rest.slice(0, cut));
 30	      rest = rest.slice(cut).trimStart();
 31	    }
 32	    lines.push(rest);
 33	  }
 34	  return lines;
 35	}
 36	
 37	function padPlain(text: string, width: number): string {
 38	  if (text.length > width) return width > 1 ? `${text.slice(0, width - 1)}…` : text.slice(0, width);
 39	  return text + " ".repeat(width - text.length);
 40	}
 41	
 42	export function cardLines(heading: string, body: string[], width = DEFAULT_CARD_WIDTH): string[] {
 43	  const cardWidth = Math.max(20, width);
 44	  const innerWidth = cardWidth - 4;
 45	  const lines: string[] = [];
 46	  lines.push(`╭${"─".repeat(cardWidth - 2)}╮`);
 47	  lines.push(`│ ${padPlain(heading, innerWidth)} │`);
 48	  lines.push(`├${"─".repeat(cardWidth - 2)}┤`);
 49	  for (const raw of body) {
 50	    const wrapped = raw.length === 0 ? [""] : wrapPlain(raw, innerWidth);
 51	    for (const line of wrapped) {
 52	      lines.push(`│ ${padPlain(line, innerWidth)} │`);
 53	    }
 54	  }
 55	  lines.push(`╰${"─".repeat(cardWidth - 2)}╯`);
 56	  return lines;
 57	}
