 59	export function artifactPreviewLines(title: string, filePath: string, maxLines = 40): string[] {
 60	  let body: string[];
 61	  try {
 62	    const raw = readFileSync(filePath, "utf8");
 63	    const allLines = raw.split("\n");
 64	    body = allLines.slice(0, maxLines);
 65	    if (allLines.length > maxLines) {
 66	      body.push("", `… ${allLines.length - maxLines} more lines (see ${filePath})`);
 67	    }
 68	  } catch {
 69	    body = [`(could not read ${filePath})`];
 70	  }
 71	  return cardLines(title, body);
 72	}
