 74	/** Read `map.get(key)` whether `map` is a Map or a JSON-deserialized plain object. */
 75	function lookup<T>(map: unknown, key: string): T | undefined {
 76	  if (map instanceof Map) return map.get(key) as T | undefined;
 77	  if (map && typeof map === "object") return (map as Record<string, T>)[key];
 78	  return undefined;
 79	}
