 99	const QUESTION_GLYPH = {
100	  unanswered: "○",
101	  answered: "●",
102	  correct: "✓",
103	  incorrect: "✗",
104	  pending_grade: "…",
105	} as const;
106	
107	function questionStatus(q: QuizQuestionish, state: QuizCardStateish): keyof typeof QUESTION_GLYPH {
108	  const graded = lookup<{ verdict?: string }>(state.openEndedGrades, q.id);
109	  if (graded?.verdict) {
110	    if (graded.verdict === "correct") return "correct";
111	    if (graded.verdict === "incorrect") return "incorrect";
112	    return "answered";
113	  }
114	  const objective = lookup<boolean>(state.objectiveResults, q.id);
115	  if (objective !== undefined) return objective ? "correct" : "incorrect";
116	  const answer = lookup<string>(state.answers, q.id);
117	  const isOpenEnded = q.type === "short_answer" || q.type === "transfer";
118	  if (isOpenEnded && answer !== undefined) return "pending_grade";
119	  return answer !== undefined ? "answered" : "unanswered";
120	}
121	
122	export function quizCardLines(quiz: Quizish, state: QuizCardStateish = {}): string[] {
123	  const body: string[] = [];
124	  let correct = 0;
125	  let graded = 0;
126	  for (const q of quiz.questions ?? []) {
127	    const status = questionStatus(q, state);
128	    if (status === "correct") correct++;
129	    if (status === "correct" || status === "incorrect") graded++;
130	    body.push(`${QUESTION_GLYPH[status]} ${q.level ? `[${q.level}] ` : ""}${q.question}`);
131	    const answer = lookup<string>(state.answers, q.id);
132	    if (answer) body.push(`   your answer: ${answer}`);
133	    const note = lookup<{ note?: string }>(state.openEndedGrades, q.id)?.note;
134	    if (note) body.push(`   feedback: ${note}`);
135	  }
136	  if (graded > 0) body.unshift(`Score: ${correct}/${graded}`, "");
137	  return cardLines(`Quiz: ${quiz.topic}`, body);
138	}
