161	export function goalCardLines(goal: Goalish): string[] {
162	  const total = goal.steps?.length ?? 0;
163	  const done = (goal.steps ?? []).filter((s) => s.status === "done").length;
164	  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
165	  const nextStep = (goal.steps ?? []).find((s) => s.status !== "done");
166	
167	  const body: string[] = [];
168	  if (goal.description) body.push(goal.description, "");
169	  body.push(`Progress: ${percent}% (${done}/${total})`, `Status: ${goal.status}`);
170	  if (nextStep) body.push(`Next: ${nextStep.title}`);
171	  body.push("");
172	  for (const step of goal.steps ?? []) {
173	    body.push(`${GOAL_STEP_GLYPH[step.status] ?? "[ ]"} ${step.order + 1}. ${step.title}${step.kind ? ` (${step.kind})` : ""}`);
174	  }
