    23	const STATE_KEY_PREFIX = "keating:openui-state:v1:";
    24	
    25	interface StoredOpenUIState {
    26		version: 1;
    27		updatedAt: number;
    28		state: Record<string, unknown>;
    29	}
    30	
    31	type StorageLike = Pick<EventStoreStorage, "getItem" | "setItem">;
