    37	export function KeatingOpenUIActionProvider({
    38		onAction,
    39		children,
    40	}: {
    41		onAction: KeatingOpenUIActionHandler;
    42		children: ReactNode;
    43	}) {
    44		return <OpenUIActionContext.Provider value={onAction}>{children}</OpenUIActionContext.Provider>;
