    47	export function openUIStateKey(documentId: string): string {
    48		return `${STATE_KEY_PREFIX}${documentId}`;
    49	}
    50	
    51	export function loadOpenUIState(
    52		storage: StorageLike | null,
    53		metadata: OpenUIDocumentMetadata,
    54	): Record<string, unknown> {
    55		if (!storage || metadata.lifecycle === "ephemeral") return {};
    56		try {
    57			const raw = storage.getItem(openUIStateKey(metadata.id));
    58			if (!raw) return {};
    59			const parsed = JSON.parse(raw) as Partial<StoredOpenUIState>;
    60			return parsed.version === 1 && parsed.state && typeof parsed.state === "object"
    61				? parsed.state
    62				: {};
    63		} catch {
    64			return {};
    65		}
    66	}
    67	
    68	export function saveOpenUIState(
    69		storage: StorageLike | null,
    70		metadata: OpenUIDocumentMetadata,
    71		state: Record<string, unknown>,
    72	): boolean {
    73		if (!storage || metadata.lifecycle === "ephemeral") return false;
    74		try {
    75			const payload: StoredOpenUIState = { version: 1, updatedAt: Date.now(), state };
    76			storage.setItem(openUIStateKey(metadata.id), JSON.stringify(payload));
    77			return true;
    78		} catch {
    79			return false;
    80		}
    81	}
