   100	}) {
   101		const hostAction = useContext(OpenUIActionContext);
   102		const [errors, setErrors] = useState<OpenUIError[]>([]);
   103		const storage = useMemo(browserStorage, []);
   104		const initialState = useMemo(
   105			() => loadOpenUIState(storage, metadata),
   106			[storage, metadata.id, metadata.lifecycle],
   107		);
   108	
   109		const handleAction = useCallback(
   110			(event: ActionEvent) => {
   111				const action: KeatingOpenUIAction = {
   112					type: event.type,
   113					humanFriendlyMessage: event.humanFriendlyMessage,
   114					params: event.params,
   115					formState: event.formState,
   116					formName: event.formName,
   117					document: metadata,
   118				};
   119				hostAction?.(action);
   120			},
   121			[hostAction, metadata],
   122		);
   123	
   124		const handleStateUpdate = useCallback(
   125			(state: Record<string, unknown>) => {
   126				saveOpenUIState(storage, metadata, state);
   127			},
   128			[storage, metadata],
   129		);
   130	
   131		return (
   132			<div
   133				data-openui-document={metadata.id}
   134				data-openui-lifecycle={metadata.lifecycle}
   135				data-openui-revision={metadata.revision}
   136				aria-busy={isStreaming}
   137			>
   138				{isStreaming ? (
   139					<div className={css({ marginBottom: "0.375rem", display: "flex", alignItems: "center", gap: "0.375rem", fontSize: "0.6875rem", color: "var(--muted-foreground)" })} role="status">
   140						<Loader2 aria-hidden="true" size={12} className={css({ animation: "spin 1s linear infinite", "@media (prefers-reduced-motion: reduce)": { animation: "none" } })} />
   141						Building interaction
   142					</div>
   143				) : null}
   144				{program ? (
   145					<div className={isStreaming ? css({ pointerEvents: "none", opacity: 0.78 }) : undefined}>
   146						<Renderer
   147							response={program}
   148							library={keatingOpenUILibrary}
   149							isStreaming={isStreaming}
   150							initialState={initialState}
   151							onAction={handleAction}
   152							onStateUpdate={handleStateUpdate}
   153							onError={setErrors}
   154						/>
   155					</div>
   156				) : null}
   157				{!isStreaming && errors.length > 0 ? (
   158					<div className={css({ marginBlock: "0.75rem", display: "flex", alignItems: "flex-start", gap: "0.5rem", borderRadius: "0.5rem", background: "color-mix(in srgb, var(--destructive) 10%, transparent)", padding: "0.75rem", fontSize: "0.75rem", color: "var(--destructive)" })} role="alert">
   159						<CircleAlert aria-hidden="true" size={15} className={css({ marginTop: "0.0625rem", flexShrink: 0 })} />
   160						<span>This interaction could not be rendered completely. The surrounding lesson is still available.</span>
   161					</div>
   162				) : null}
   163			</div>
   164		);
   165	}
