338	export async function launchShell(cwd: string, args: string[]): Promise<number> {
339	  await ensureProjectScaffold(cwd);
340	  const config = await loadKeatingConfig(cwd);
341	  await syncPiSettings(cwd, config);
342	  await syncExtraProviders(cwd, process.env);
343	  const report = await detectAiRuntime(cwd);
344	  const runtime = report.selected;
345	  if (!runtime) {
346	    throw new Error(missingRuntimeMessage(report));
347	  }
348	
349	  const packageRoot = resolvePackageRoot();
350	  const isDist = __dirname.replace(/\\/g, "/").includes("/dist/src/runtime");
351	
352	  const extensionPath = isDist
353	    ? join(__dirname, "..", "pi", "hyper-teacher", "index.js")
354	    : join(packageRoot, "dist", "src", "pi", "hyper-teacher", "index.js");
355	
356	  if (!existsSync(extensionPath)) {
357	    throw new Error([
358	      `Missing built extension: ${extensionPath}.`,
359	      "",
360	      "Recover with:",
361	      "  bun run build",
362	      "  npm run build",
363	      "",
364	      "If this came from an installed package, reinstall Keating:",
365	      "  npm install -g keating"
366	    ].join("\n"));
367	  }
368	
369	  const promptDir = join(packageRoot, "pi", "prompts");
370	  const skillsDir = join(packageRoot, "pi", "skills");
371	  const systemPromptPath = join(packageRoot, "SYSTEM.md");
372	  const systemPrompt = readFileSync(systemPromptPath, "utf8");
373	  const authSelection = selectAuthenticatedProvider(cwd, config, args);
374	  if (authSelection.note) {
375	    console.error(authSelection.note);
376	  }
377	
378	  const sharedArgs = mergePiDefaultsWithOverrides(config, [
379	    "--session-dir",
380	    sessionsDir(cwd),
381	    "--extension",
382	    extensionPath,
383	    "--prompt-template",
384	    promptDir,
385	    "--skill",
386	    skillsDir,
387	    "--append-system-prompt",
388	    systemPrompt,
389	    "--tools",
390	    "read,bash,edit,write,grep,find,ls",
391	    ...args
392	  ], { provider: authSelection.provider, model: authSelection.model });
393	
394	  const child =
395	    runtime.kind === "binary"
396	      ? spawn(runtime.command, sharedArgs, {
397	          cwd,
398	          stdio: "inherit",
399	          env: {
400	            ...authSelection.env,
401	            KEATING_AUTH_MISSING_PROVIDER: authSelection.missingProvider ?? "",
402	            PI_SKIP_VERSION_CHECK: process.env.PI_SKIP_VERSION_CHECK ?? "1",
403	            PI_CODING_AGENT_DIR: configDir(cwd)
404	          }
405	        })
406	      : spawn(runtime.command, [runtime.cliPath!, ...sharedArgs], {
407	          cwd,
408	          stdio: "inherit",
409	          env: {
410	            ...authSelection.env,
411	            KEATING_AUTH_MISSING_PROVIDER: authSelection.missingProvider ?? "",
412	            PI_SKIP_VERSION_CHECK: process.env.PI_SKIP_VERSION_CHECK ?? "1",
413	            PI_CODING_AGENT_DIR: configDir(cwd)
414	          }
415	        });
416	
417	  return await new Promise<number>((resolvePromise, reject) => {
418	    child.on("error", reject);
419	    child.on("exit", (code: number | null) => resolvePromise(code ?? 0));
420	  });
421	}
