438	  const packageRoot = resolvePackageRoot();
439	  const isDist = __dirname.replace(/\\/g, "/").includes("/dist/src/runtime");
440	  const extensionPath = isDist
441	    ? join(__dirname, "..", "pi", "hyper-teacher", "index.js")
442	    : join(packageRoot, "dist", "src", "pi", "hyper-teacher", "index.js");
443	  if (!existsSync(extensionPath)) {
444	    throw new Error(`Missing built extension: ${extensionPath}. Run bun run build before keating tui.`);
445	  }
446	
447	  const promptDir = join(packageRoot, "pi", "prompts");
448	  const skillsDir = join(packageRoot, "pi", "skills");
449	  const systemPrompt = readFileSync(join(packageRoot, "SYSTEM.md"), "utf8");
450	  const authSelection = selectAuthenticatedProvider(cwd, config, args);
451	  if (authSelection.note) console.error(authSelection.note);
