 50	function messageText(message: unknown): string {
 51	  const content = (message as { content?: unknown } | null)?.content;
 52	  if (typeof content === "string") return content;
 53	  if (!Array.isArray(content)) return "";
 54	  return content
 55	    .map((part) => {
 56	      if (!part || typeof part !== "object") return "";
 57	      const candidate = part as { type?: string; text?: string };
 58	      return candidate.type === "text" && typeof candidate.text === "string" ? candidate.text : "";
 59	    })
 60	    .filter(Boolean)
 61	    .join("\n");
 62	}
 63	
 64	function briefArgs(args: unknown): string {
 65	  if (!args || typeof args !== "object") return "";
 66	  const entries = Object.entries(args as Record<string, unknown>)
 67	    .filter(([, value]) => typeof value === "string" || typeof value === "number" || typeof value === "boolean")
 68	    .slice(0, 3)
 69	    .map(([key, value]) => {
 70	      const text = String(value);
 71	      return `${key}=${text.length > 40 ? `${text.slice(0, 40)}…` : text}`;
 72	    });
 73	  return entries.join(", ");
