    39	/** Choose across domains before showing a second prompt from the same domain. */
    40	export function pickDiverseStarterPrompts(
    41		pool: readonly StarterPrompt[],
    42		count: number,
    43		random: () => number = Math.random,
    44	): StarterPrompt[] {
    45		if (count <= 0 || pool.length === 0) return [];
    46		const byDomain = new Map<string, StarterPrompt[]>();
    47		for (const prompt of shuffled(pool, random)) {
    48			const entries = byDomain.get(prompt.domain) ?? [];
    49			entries.push(prompt);
    50			byDomain.set(prompt.domain, entries);
    51		}
    52		const selected: StarterPrompt[] = [];
    53		let domains = shuffled([...byDomain.keys()], random);
    54		while (selected.length < Math.min(count, pool.length) && domains.length > 0) {
    55			const nextDomains: string[] = [];
    56			for (const domain of domains) {
    57				const prompt = byDomain.get(domain)?.shift();
    58				if (prompt) selected.push(prompt);
    59				if ((byDomain.get(domain)?.length ?? 0) > 0) nextDomains.push(domain);
    60				if (selected.length >= count) break;
    61			}
    62			domains = shuffled(nextDomains, random);
    63		}
    64		return selected;
    65	}

